// Normalize lead data from different sources into consistent format
const items = $input.all();
const normalizedLeads = [];

for (const item of items) {
  let lead = {
    timestamp: new Date().toISOString(),
    source: '',
    name: '',
    phone: '',
    email: '',
    budget: '',
    propertyType: '',
    preapprovalStatus: 'Unknown',
    lastContact: new Date().toISOString(),
    status: 'New',
    leadScore: 'Unqualified',
    timeline: '',
    priorities: '',
    notes: '',
    propertiesSent: '',
    viewingsScheduled: '',
    engagementScore: 0
  };

  // Detect source and normalize fields
  const json = item.json;

  // Zillow leads
  if (json.body?.source === 'zillow' || json.query?.source === 'zillow') {
    lead.source = 'Zillow';
    lead.name = json.body?.name || json.body?.customer_name || '';
    lead.phone = json.body?.phone || json.body?.phone_number || '';
    lead.email = json.body?.email || '';
    lead.budget = json.body?.budget || json.body?.price_range || '';
    lead.propertyType = json.body?.property_type || json.body?.home_type || '';
    lead.priorities = json.body?.message || json.body?.notes || '';
  }

  // Realtor.com leads
  else if (json.body?.source === 'realtor' || json.query?.source === 'realtor') {
    lead.source = 'Realtor.com';
    lead.name = json.body?.name || json.body?.full_name || '';
    lead.phone = json.body?.phone || json.body?.mobile || '';
    lead.email = json.body?.email || '';
    lead.budget = json.body?.max_price || json.body?.budget || '';
    lead.propertyType = json.body?.property_type || '';
    lead.priorities = json.body?.comments || json.body?.message || '';
  }

  // Website contact form
  else if (json.body?.source === 'website' || json.query?.source === 'website') {
    lead.source = 'Website';
    lead.name = json.body?.name || json.body?.full_name || '';
    lead.phone = json.body?.phone || json.body?.phone_number || '';
    lead.email = json.body?.email || '';
    lead.budget = json.body?.budget || json.body?.price_range || '';
    lead.propertyType = json.body?.property_type || json.body?.looking_for || '';
    lead.priorities = json.body?.message || json.body?.comments || json.body?.notes || '';
  }

  // Gmail referrals
  else if (json.from || json.subject?.includes('Referral')) {
    lead.source = 'Email Referral';
    lead.email = json.from || '';

    // Extract name from email subject or body
    const subjectMatch = json.subject?.match(/Referral:\s*([^<]+)/);
    lead.name = subjectMatch ? subjectMatch[1].trim() : 'Unknown';

    // Extract phone from email body (basic regex)
    const phoneMatch = json.textPlain?.match(/(\+?1?[-.]?\(?\d{3}\)?[-.]?\d{3}[-.]?\d{4})/);
    lead.phone = phoneMatch ? phoneMatch[1] : '';

    lead.notes = 'Referral from: ' + (json.from || 'Unknown');
    lead.priorities = json.textPlain?.substring(0, 500) || '';
  }

  // Twilio phone calls
  else if (json.From || json.CallSid) {
    lead.source = 'Phone Call';
    lead.phone = json.From || json.Caller || '';
    lead.name = 'Unknown (Call)';
    lead.notes = `Call SID: ${json.CallSid || 'N/A'} | Status: ${json.CallStatus || 'N/A'}`;

    // If voicemail transcription available
    if (json.TranscriptionText) {
      lead.priorities = json.TranscriptionText;
    }
  }

  // Clean phone number (remove non-digits except +)
  if (lead.phone) {
    lead.phone = lead.phone.replace(/[^\d+]/g, '');
  }

  // Clean budget (extract numbers)
  if (lead.budget && typeof lead.budget === 'string') {
    const budgetMatch = lead.budget.match(/\$?([\d,]+)/);
    if (budgetMatch) {
      lead.budget = budgetMatch[1].replace(/,/g, '');
    }
  }

  normalizedLeads.push({ json: lead });
}

return normalizedLeads;

